CHECKS = [
    "check_shared_projection",
    "check_sparse_indices",
    "check_solve_u_lambda",
    "check_forward_delta",
    "check_delta_weight",
]


def _t(x, dtype=torch.float64):
    return torch.tensor(x, dtype=dtype)


def check_shared_projection(solve):
    f = EXPECTED["F1"]
    mats = [_t(w) for w in f["weights"]]
    v = solve(mode="shared_projection", matrices=mats,
              regularization_alpha=f["alpha"]).to(torch.float64)
    assert torch.allclose(v, _t(f["v_wide"]), atol=1e-6), float((v - _t(f["v_wide"])).abs().max())
    # 瘦阵路径: 行 < 列 → SVD, V 行正交 + 锚点逐位比对（vh 与 vh.T 都正交，必须比锚点）
    f2 = EXPECTED["F2"]
    v2 = solve(mode="shared_projection", matrices=[_t(f2["w_thin"])],
               regularization_alpha=f["alpha"]).to(torch.float64)
    assert torch.allclose(v2, _t(f2["v_thin"]), atol=1e-6), float((v2 - _t(f2["v_thin"])).abs().max())
    err = (v2 @ v2.T - torch.eye(v2.shape[0], dtype=torch.float64)).abs().max()
    assert err < 1e-6, err


def check_sparse_indices(solve):
    f = EXPECTED["F3"]
    idx = solve(mode="sparse_indices", in_dim=f["in_dim"], sparse_rate=0.05,
                prng_key=f["prng_key"])
    assert torch.equal(idx, _t(f["idx005"], torch.long)), idx
    idx2 = solve(mode="sparse_indices", in_dim=f["in_dim"], sparse_rate=0.3,
                 prng_key=f["prng_key"])
    assert torch.equal(idx2, _t(f["idx03"], torch.long)), idx2
    # nnz = max(1, int(in²·rate)) = max(1, int(10.8)) = 10
    assert idx2.shape[1] == 10
    # 无对角位置
    assert (idx2[0] != idx2[1]).all()
    # prng 决定排列
    idx3 = solve(mode="sparse_indices", in_dim=f["in_dim"], sparse_rate=0.3, prng_key=7)
    assert torch.equal(idx3, _t(f["idx03_k7"], torch.long))
    assert not torch.equal(idx2, idx3)
    # sparse_rate=0 → 空索引
    idx0 = solve(mode="sparse_indices", in_dim=4, sparse_rate=0.0, prng_key=0)
    assert idx0.shape == (2, 0)


def check_solve_u_lambda(solve):
    f = EXPECTED["F4"]
    v = _t(EXPECTED["F1"]["v_wide"])
    u, lam = solve(mode="solve_u_lambda", w=_t(f["w_sq"]), v=v)
    assert torch.allclose(u, _t(f["u"]), atol=1e-12), float((u - _t(f["u"])).abs().max())
    assert torch.allclose(lam, _t(f["lambda"]), atol=1e-12)
    # U 列单位范数
    assert torch.allclose(u.norm(dim=0), torch.ones(u.shape[1], dtype=torch.float64), atol=1e-12)
    # 精确重构恒等: U diag(λ) Vᵀ == W
    recon = u @ torch.diag(lam) @ v.T
    assert torch.allclose(recon, _t(f["w_sq"]), atol=1e-10), float((recon - _t(f["w_sq"])).abs().max())
    # 病态 V: pinv(rt ol=1e-6) 会截断小奇异方向，solve 主路径不截断——锚点区分两者
    f7 = EXPECTED["F7"]
    u7, lam7 = solve(mode="solve_u_lambda", w=_t(f7["w_ill"]), v=_t(f7["v_ill"]))
    assert torch.allclose(u7, _t(f7["u_ill"]), atol=1e-9), float((u7 - _t(f7["u_ill"])).abs().max())
    assert torch.allclose(lam7, _t(f7["lambda_ill"]), atol=1e-9)
    recon7 = u7 @ torch.diag(lam7) @ _t(f7["v_ill"]).T
    assert torch.allclose(recon7, _t(f7["w_ill"]), atol=1e-9), float((recon7 - _t(f7["w_ill"])).abs().max())


def check_forward_delta(solve):
    f = EXPECTED["F5"]
    v = _t(EXPECTED["F1"]["v_wide"])
    f4 = EXPECTED["F4"]
    fd = solve(mode="forward_delta", x=_t(f["x"]), w=_t(f4["w_sq"]), v=v,
               s_values=_t(f["s_values"]), s_indices=_t(f["indices"], torch.long),
               s_size=(6, 6),
               lambda_l=_t(f4["lambda"]), u=_t(f4["u"]))
    assert torch.allclose(fd, _t(f["forward"]), atol=1e-10), float((fd - _t(f["forward"])).abs().max())
    # 互证: x @ ΔWᵀ == forward_delta
    dw = _t(f["delta_w"])
    assert torch.allclose(_t(f["x"]) @ dw.T, fd, atol=1e-10)


def check_delta_weight(solve):
    f = EXPECTED["F5"]
    f4 = EXPECTED["F4"]
    v = _t(EXPECTED["F1"]["v_wide"])
    dw = solve(mode="delta_weight", w=_t(f4["w_sq"]), u=_t(f4["u"]), v=v,
               s_values=_t(f["s_values"]), s_indices=_t(f["indices"], torch.long),
               s_size=(6, 6), lambda_l=_t(f4["lambda"]))
    assert torch.allclose(dw, _t(f["delta_w"]), atol=1e-12), float((dw - _t(f["delta_w"])).abs().max())
    # init_weights=True: S values 全零 → ΔW 精确为 0（参数化恒等）
    dw0 = solve(mode="delta_weight", w=_t(f4["w_sq"]), u=_t(f4["u"]), v=v,
                s_values=torch.zeros(len(f["s_values"]), dtype=torch.float64),
                s_indices=_t(f["indices"], torch.long), s_size=(6, 6),
                lambda_l=_t(f4["lambda"]))
    assert dw0.abs().max() < 1e-10, float(dw0.abs().max())
    # 稀疏重建: sparse_dense 与 (indices, values, size) 一致
    s = solve(mode="sparse_dense", values=_t(f["s_values"]),
              indices=_t(f["indices"], torch.long), size=(6, 6))
    assert s.shape == (6, 6)
    assert s[_t(f["indices"], torch.long)[0], _t(f["indices"], torch.long)[1]].tolist() == _t(f["s_values"]).tolist()
